const en = { 'Light tone': 'Light' };
const dictionaries = { en, ru, uk, es, fr, de, 'zh-Hans': zh, ja };
let current = 'en';

/// The setting's language, or the browser's first one the reader has.
export function resolve(setting) {
    if (setting && setting !== 'auto' && languages[setting]) return setting;
    for (const wanted of navigator.languages || [navigator.language || 'en']) {
        const code = wanted.toLowerCase();
        if (code.startsWith('zh')) return 'zh-Hans';
        const base = code.split('-')[0];
        if (languages[base]) return base;
    }
    return 'en';
}

export function setLanguage(code) {
    current = languages[code] ? code : 'en';
    document.documentElement.lang = current;
}

export const language = () => current;

export const t = (text) => dictionaries[current]?.[text] ?? text;

/// A converter's message in the reader's language; as it was where no
/// rule says it.
export function problem(message) {
    for (const [pattern, words] of problems[current] || []) {
        if (pattern.test(message)) return message.replace(pattern, words);
    }
    return message;
}

/// «p. 12», as each language writes a page.
export function pageLabel(page) {
    switch (current) {
    case 'ru': case 'uk': return `с. ${page}`;
    case 'de': return `S. ${page}`;
    case 'zh-Hans': return `第 ${page} 页`;
    case 'ja': return `${page} ページ`;
    default: return `p. ${page}`;
    }
}
